mapper.select:
SELECT sr.bus_no AS busNo, sup.name AS supplierName, sr.status_enum AS statusEnum, MAX(creator.name) AS creatorName, MAX(approver.name) AS approverName, SUM(sr.total_price) AS totalAmount, MAX(sr.approval_time) AS approvalTime, MAX(sr.apply_time) AS applyTime FROM wkf_supply_request sr LEFT JOIN cus_supplier sup ON sup.id = sr.supplier_id AND sup.is_deleted = 0 LEFT JOIN adm_practitioner creator ON creator.id = sr.created_by LEFT JOIN adm_practitioner approver ON approver.id = sr.approver_id WHERE sr.type_enum = 'CABINET_INBOUND_RECEIPT' AND sr.is_deleted = 0
AND sr.bus_no LIKE CONCAT('%', #{query.keyword}, '%')
AND sr.apply_time >= #{query.applyTimeFrom}
AND sr.apply_time <= #{query.applyTimeTo}
AND sr.purpose_location_id = #{query.purposeLocationId}
GROUP BY sr.bus_no ORDER BY MAX(sr.created_at) DESC
